python3 -c "
import json
# Read the Llama eval s42 AR results (TF and AR)
paths = [
    '/root/turn_residual_gating/runs/eval_llama_tg_s42/ar_base_ours/base_model_gar.json',
    '/root/turn_residual_gating/runs/eval_llama_tg_s42/ar_tg_ours/epoch_2_gar.json',
]
for p in paths:
    try:
        with open(p) as f:
            d = json.load(f)
        if 'results' in d:
            for bk, bv in d['results'].items():
                if 'avg_gar_per_turn' in bv:
                    pt = bv['avg_gar_per_turn']
                    print(f'{p.split(\"/\")[-2]} {bk}: per_turn={[round(x,4) for x in pt]}, mid_gar={bv.get(\"mid_turns_avg_gar\",\"N/A\")}')
        elif 'avg_gar_per_turn' in d:
            pt = d['avg_gar_per_turn']
            print(f'{p.split(\"/\")[-2]}: per_turn={[round(x,4) for x in pt]}')
        elif 'conversations' in d:
            convs = d['conversations']
            n_turns = max(len(c.get('gar_per_turn',[])) for c in convs)
            avg = []
            for t in range(n_turns):
                vals = [c['gar_per_turn'][t] for c in convs if len(c['gar_per_turn']) > t]
                avg.append(sum(vals)/len(vals))
            print(f'{p.split(\"/\")[-2]}: per_turn={[round(x,4) for x in avg]}')
    except Exception as e:
        print(f'{p}: ERROR {e}')
"
